#!/usr/bin/env node
// Generates the error code constants for every layer from errors/errors.json.
//
//   node scripts/generate-error-codes.mjs          write the generated files
//   node scripts/generate-error-codes.mjs --check  fail if any file is stale
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = JSON.parse(
  readFileSync(path.join(root, 'errors/errors.json'), 'utf8')
);

const header = (comment) =>
  `${comment} @generated by scripts/generate-error-codes.mjs from errors/errors.json. Do not edit.`;

const categories = source.categories;
const codes = categories.flatMap((category) => category.codes);

const seen = new Set();
for (const { code } of codes) {
  if (!/^[A-Z][A-Z_]*[A-Z]$/.test(code)) {
    throw new Error(`Invalid error code name: ${code}`);
  }
  if (seen.has(code)) {
    throw new Error(`Duplicate error code: ${code}`);
  }
  seen.add(code);
}

const typescript = `${header('//')}

/**
 * Every code a \`BluetoothClassicError\` can carry. See docs/errors.md.
 */
export const ErrorCode = {
${codes
  .map(({ code, description }) => `  /** ${description} */\n  ${code}: '${code}',`)
  .join('\n')}
} as const;

export type ErrorCode = (typeof ErrorCode)[keyof typeof ErrorCode];

export const ERROR_CODES: readonly ErrorCode[] = Object.freeze(
  Object.values(ErrorCode)
);
`;

const kotlin = `${header('//')}
package kjd.reactnative.bluetooth

/** Error codes shared with JavaScript. See docs/errors.md. */
object ErrorCode {
${codes.map(({ code }) => `  const val ${code} = "${code}"`).join('\n')}
}
`;

const swift = `${header('//')}

/// Error codes shared with JavaScript. See docs/errors.md.
enum ErrorCode {
${codes.map(({ code }) => `  static let ${code} = "${code}"`).join('\n')}
}
`;

const objc = `${header('//')}
#import <Foundation/Foundation.h>

// Error codes shared with JavaScript. See docs/errors.md.
${codes
  .map(({ code }) => `static NSString *const RNBCErrorCode_${code} = @"${code}";`)
  .join('\n')}
`;

const markdown = `<!-- ${header('').trim()} -->

# Error codes

Every failure is a \`BluetoothClassicError\` with one of these \`code\` values, on both platforms.
Compare against the exported \`ErrorCode\` constants:

\`\`\`ts
import { ErrorCode, isBluetoothClassicError } from '@dynlabs/react-native-bluetooth-classic';

try {
  await connect(address);
} catch (error) {
  if (isBluetoothClassicError(error, ErrorCode.CONNECT_TIMEOUT)) {
    // retry later
  }
}
\`\`\`

Besides \`code\` and \`message\`, an error can carry \`platform\`, \`deviceId\`, \`connectionId\`,
\`missingPermissions\`, \`nativeCode\` and \`nativeMessage\`. \`JSON.stringify(error)\` includes all of them.

${categories
  .map(
    (category) => `## ${category.name}

| Code | Meaning | What to do |
|---|---|---|
${category.codes
  .map(
    ({ code, description, troubleshooting }) =>
      `| \`${code}\` | ${description} | ${troubleshooting} |`
  )
  .join('\n')}
`
  )
  .join('\n')}`;

const outputs = {
  'src/errors/ErrorCode.ts': typescript,
  'android/src/main/java/kjd/reactnative/bluetooth/ErrorCode.kt': kotlin,
  'ios/RNBCErrorCode.h': objc,
  'ios/Core/Sources/BluetoothClassicCore/ErrorCode.swift': swift,
  'docs/errors.md': markdown,
};

const check = process.argv.includes('--check');
const stale = [];

for (const [file, contents] of Object.entries(outputs)) {
  const target = path.join(root, file);
  const current = existsSync(target) ? readFileSync(target, 'utf8') : null;
  if (current === contents) {
    continue;
  }
  if (check) {
    stale.push(file);
  } else {
    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, contents);
    console.log(`Wrote ${file}`);
  }
}

if (stale.length > 0) {
  console.error(
    `Generated error code files are out of date:\n  ${stale.join('\n  ')}\nRun \`yarn errors:generate\`.`
  );
  process.exit(1);
}

if (check) {
  console.log(`Error codes are up to date (${codes.length} codes).`);
}
